L112: /** The plugin's .mcp.json cannot do discovery, so the daily job checks it against discovery instead. */
L113: export function verifyMcpJson(text: string, discovery: Discovery, baseUrl: string): string | null {
L114:   const parsed = JSON.parse(text) as { mcpServers?: Record<string, { url?: string; headers?: Record<string, string> }> };
L115:   const entry = parsed.mcpServers?.truescrape;
L116:   if (!entry) return '.mcp.json has no mcpServers.truescrape entry';
L117: 
L118:   let expectedUrl: string;
L119:   try {
L120:     expectedUrl = `${baseUrl.replace(/\/$/, '')}${new URL(discovery.endpoint).pathname}`;
L121:   } catch {
L122:     expectedUrl = discovery.endpoint;
L123:   }
L124:   // The plugin narrows its toolset with ?platforms=, which discovery knows nothing about.
L125:   if (entry.url?.split('?')[0] !== expectedUrl) return `.mcp.json url is ${entry.url}; discovery says ${expectedUrl}`;
L126: 
L127:   const headers = Object.keys(entry.headers ?? {}).map((h) => h.toLowerCase());
L128:   if (!headers.includes(discovery.authentication.name.toLowerCase())) {
L129:     return `.mcp.json sends ${headers.join(', ') || 'no headers'}; discovery wants ${discovery.authentication.name}`;
L130:   }
L131:   return null;
L132: }
